class CGI_IMAGE(GeneralRecommender):
    def __init__(self, config, dataset):
        super(CGI_IMAGE, self).__init__(config, dataset)

        num_user = self.n_users
        num_item = self.n_items
        batch_size = config['train_batch_size']  # not used
        dim_x = config['embedding_size']
        self.embedding_size = config['feat_embed_dim']
        self.feat_embed_dim = config['feat_embed_dim']
        self.n_layers = config['n_layers']
        self.knn_k = config['knn_k']
        self.mm_image_weight = config['mm_image_weight']

        self.batch_size = batch_size
        self.num_user = num_user
        self.num_item = num_item
        self.k = 40
        self.aggr_mode = 'add'
        self.dataset = dataset
        self.dropout = config['dropout']
        self.reg_weight = config['reg_weight']

        self.temp = config['temp']
        self.drop_rate = 0.1
        self.v_rep = None
        self.t_rep = None
  

        
        
        self.id_preference = None
        self.dim_latent = 64
        self.dim_feat = 128
   
        self.v_preference = nn.Parameter(nn.init.xavier_normal_(torch.tensor(
                np.random.randn(self.n_users, self.dim_latent), dtype=torch.float32, requires_grad=True),
                gain=1).to(self.device))

        


        dataset_path = os.path.abspath(config['data_path'] + config['dataset'])
        self.user_graph_dict = np.load(os.path.join(dataset_path, config['user_graph_dict_file']),
                                       allow_pickle=True).item()

       

        if self.v_feat is not None:
            self.image_trs = nn.Linear(self.v_feat.shape[1], self.feat_embed_dim)
        # if self.t_feat is not None:
        #     self.text_trs = nn.Linear(self.t_feat.shape[1], self.feat_embed_dim)
        self.sparse = True
        self.image_knn_k = config['image_knn_k']
        image_adj_file = os.path.join(dataset_path, 'image_adj_{}_{}.pt'.format(self.image_knn_k, self.sparse))
        if os.path.exists(image_adj_file):
                image_adj = torch.load(image_adj_file)
        else:
            image_adj = build_sim(self.v_feat.detach())
            image_adj = build_knn_normalized_graph(image_adj, topk=self.image_knn_k, is_sparse=self.sparse,
                                                    norm_type='sym')
            torch.save(image_adj, image_adj_file)
        self.image_original_adj = image_adj.to(self.device)
        self.walk_length = config['walk_length']
        self.ssl_temp = config['ssl_temp']
        self.choosing_tmp = config['choosing_tmp']
        self.ssl_weight = config['ssl_weight']
        self.interaction_matrix  = dataset.inter_matrix(form='coo').astype(np.float32)
        self.create_sparse_adjaceny() 
        self.edge_mask_learner = nn.ModuleList([nn.Sequential(nn.Linear(2 * self.embedding_size, self.embedding_size), nn.ReLU(), nn.Linear(self.embedding_size, 1)) for i in range(self.n_layers)])
        



        self.result_embed = nn.Parameter(
            nn.init.xavier_normal_(torch.tensor(np.random.randn(self.n_users + self.n_items, dim_x)))).to(self.device)

    def pack_item_edge_index(self):
        edge_src = [] 
        edge_dst = [] 
        edge_weights = []
        for item_id,(nbr_list,w_list) in self.item_graph_dict.items():
            for nbr_id,w in zip(nbr_list,w_list):
                edge_src.append(item_id)
                edge_dst.append(nbr_id)
                edge_weights.append(w)
                edge_src.append(nbr_id)
                edge_dst.append(item_id)
                edge_weights.append(w)
        edge_index = torch.tensor([edge_src, edge_dst], dtype=torch.long)
        edge_weight = torch.tensor(edge_weights, dtype=torch.float)

        return edge_index, edge_weight

    def get_knn_adj_mat(self, mm_embeddings):
        context_norm = mm_embeddings.div(torch.norm(mm_embeddings, p=2, dim=-1, keepdim=True))
        sim = torch.mm(context_norm, context_norm.transpose(1, 0))
        _, knn_ind = torch.topk(sim, self.knn_k, dim=-1)
        adj_size = sim.size()
        del sim
        # construct sparse adj
        indices0 = torch.arange(knn_ind.shape[0]).to(self.device)
        indices0 = torch.unsqueeze(indices0, 1)
        indices0 = indices0.expand(-1, self.knn_k)
        indices = torch.stack((torch.flatten(indices0), torch.flatten(knn_ind)), 0)
        # norm
        return indices, self.compute_normalized_laplacian(indices, adj_size)

    def compute_normalized_laplacian(self, indices, adj_size):
        adj = torch.sparse.FloatTensor(indices, torch.ones_like(indices[0]), adj_size)
        row_sum = 1e-7 + torch.sparse.sum(adj, -1).to_dense()
        r_inv_sqrt = torch.pow(row_sum, -0.5)
        rows_inv_sqrt = r_inv_sqrt[indices[0]]
        cols_inv_sqrt = r_inv_sqrt[indices[1]]
        values = rows_inv_sqrt * cols_inv_sqrt
        return torch.sparse.FloatTensor(indices, values, adj_size)

    def pre_epoch_processing(self):
        pass

    def pack_edge_index(self, inter_mat):
        rows = inter_mat.row
        cols = inter_mat.col + self.n_users
        return np.column_stack((rows, cols))

    def InfoNCE(self, view1, view2, temp=0.2):
        view1, view2 = F.normalize(view1, dim=1), F.normalize(view2, dim=1)
        pos_score = (view1 * view2).sum(dim=-1)
        pos_score = torch.exp(pos_score / temp)
        ttl_score = torch.matmul(view1, view2.transpose(0, 1))
        ttl_score = torch.exp(ttl_score / temp).sum(dim=1)
        cl_loss = -torch.log(pos_score / ttl_score)
        return torch.mean(cl_loss)
    def BPR(self,result_embed):
        user_tensor = result_embed[self.user_nodes]
        pos_item_tensor = result_embed[self.pos_item_nodes]
        neg_item_tensor = result_embed[self.neg_item_nodes]

        pos_scores = torch.sum(user_tensor * pos_item_tensor, dim=1)
        neg_scores = torch.sum(user_tensor * neg_item_tensor, dim=1)
        loss_rec = -torch.mean(torch.log2(torch.sigmoid(pos_scores - neg_scores)))
        return loss_rec

    def forward(self):
    
        edge_mask_list = [] 
     
        
        v_feat_ori = self.image_trs(self.v_feat)
        v_feat = torch.sparse.mm(self.image_original_adj,v_feat_ori) 
        
        
        x_v= torch.cat((self.v_preference,v_feat),dim=0) 
        x_v = F.normalize(x_v) 
        
        
        cur_embedding = x_v 
        all_embeddings = [cur_embedding]
        edge_mask_list = [] 

        
        for i in range(self.n_layers):
            cur_embedding = torch.mm(self.norm_adj, cur_embedding)
            all_embeddings.append(cur_embedding)

            # edge_num * 2emebdding_size
            edge_cat_embedding = torch.cat([cur_embedding[self.row], cur_embedding[self.col]], dim=-1)
            edge_mask = self.edge_mask_learner[i](edge_cat_embedding)
            bias = 0.0 + 0.0001  # If bias is 0, we run into problems
            eps = (bias - (1 - bias)) * torch.rand(edge_mask.size()) + (1 - bias)
            edge_gate_inputs = torch.log(eps) - torch.log(1 - eps)
            edge_gate_inputs = edge_gate_inputs.to(self.device)
            edge_gate_inputs = (edge_gate_inputs + edge_mask) / self.choosing_tmp
            edge_mask = torch.sigmoid(edge_gate_inputs).squeeze(1)
            edge_mask_list.append(edge_mask)

        all_embeddings = torch.stack(all_embeddings, dim=0)
        all_embeddings = torch.sum(all_embeddings, dim=0, keepdim=False)
        self.result_embed = all_embeddings 

        # edge_dropout_view##################
        
        cur_embedding_edge_drop =  x_v
        all_embeddings_edge_drop = [cur_embedding_edge_drop]

        # # # edge_reg = 0
        for i in range(self.n_layers):
            edge_mask = edge_mask_list[i]
            new_edge = torch.mul(self.norm_adj.values(), edge_mask)
            # edge_reg += new_edge.sum()/len(self.interact_matrix)

            cur_embedding_edge_drop = torch_sparse.spmm(self.norm_adj.indices(), new_edge, self.n_users + self.n_items, self.n_users + self.n_items, cur_embedding_edge_drop)
            all_embeddings_edge_drop.append(cur_embedding_edge_drop)

        all_embeddings_edge_drop = torch.stack(all_embeddings_edge_drop, dim=0)
        all_embeddings_edge_drop = torch.sum(all_embeddings_edge_drop, dim=0, keepdim=False)
        
        # # edge_reg = edge_reg / self.n_layers

        # # build result embedding
        self.result_embed_ED = all_embeddings_edge_drop

        


    def buildItemGraph(self, h):
        for i in range(self.n_layers):
            h = torch.sparse.mm(self.mm_adj, h)
        return h


    def calculate_loss(self, interaction):
       
        self.user_nodes, self.pos_item_nodes, self.neg_item_nodes = interaction[0], interaction[1], interaction[2]
        self.pos_item_nodes += self.n_users
        self.neg_item_nodes += self.n_users
        
        self.forward() 
        # result_embed = self.forward(interaction)
        ## Rec Loss 
        loss_rec_v = self.BPR(self.result_embed) 
        loss_rec_ed = self.BPR(self.result_embed_ED) 
        loss_rec = loss_rec_v + loss_rec_ed
        
        
       
        loss_user_edge = self.InfoNCE(self.result_embed_ED[self.user_nodes],self.result_embed[self.user_nodes])
        loss_item_edge = self.InfoNCE(self.result_embed_ED[self.pos_item_nodes],self.result_embed[self.pos_item_nodes])
    
        loss_ssl = self.ssl_weight* (loss_user_edge+loss_item_edge)
        

        reg_embedding_loss_t = (self.v_preference[self.user_nodes] ** 2).mean() if self.v_preference is not None else 0.0
        reg_loss = self.reg_weight * (reg_embedding_loss_t)
        
        loss = loss_rec + loss_ssl +reg_loss
 
        
        return loss 

