    def print_embd(self):
        return self.result_embed_v, self.result_embed_t
    
    def mask_noise(self,x,mask_token,mask_rate=0.1):
      
        perm = torch.randperm(self.n_items, device=x.device)
        num_mask_items = int(mask_rate*self.n_items)
        mask_items = perm[:num_mask_items]
        keep_items = perm[num_mask_items]
        mask_x = x.clone()
        token_nodes = mask_items.clone()
        mask_x[mask_items] = 0 
        mask_x[token_nodes] += mask_token

        
        return  mask_x,mask_items,keep_items
    def get_adj_mat(self):
        adj_mat = sp.dok_matrix((self.n_users + self.n_items, self.n_users + self.n_items), dtype=np.float32)
        adj_mat = adj_mat.tolil()
        R = self.interaction_matrix.tolil()

        adj_mat[:self.n_users, self.n_users:] = R
        adj_mat[self.n_users:, :self.n_users] = R.T
        adj_mat = adj_mat.todok()

        def normalized_adj_single(adj):
            rowsum = np.array(adj.sum(1))
            rowsum[rowsum == 0] = 1  # 避免除0错误
            
            d_inv = np.power(rowsum, -0.5).flatten()
            d_inv[np.isinf(d_inv)] = 0.
            d_mat_inv = sp.diags(d_inv)

            norm_adj = d_mat_inv.dot(adj_mat)
            norm_adj = norm_adj.dot(d_mat_inv)
            return norm_adj.tocoo()

        norm_adj_mat = normalized_adj_single(adj_mat)
        norm_adj_mat = norm_adj_mat.tolil()
        self.R = norm_adj_mat[:self.n_users, self.n_users:]
        return norm_adj_mat.tocsr()
    def create_sparse_adjaceny(self):
        """
        复现 create_sparse_adjaceny 的邻接矩阵构造方法
        """
        # 直接从 interaction_matrix 提取 COO 格式的索引和值
        coo_matrix = self.interaction_matrix.tocoo()
        self.row = torch.from_numpy(coo_matrix.row).long()
        self.col = torch.from_numpy(coo_matrix.col).long()
        values = torch.from_numpy(coo_matrix.data).float()

        # 交互矩阵 (user_num, item_num) 的 PyTorch 版本
        self.interact_matrix = torch.sparse_coo_tensor(
            indices=torch.stack([self.row, self.col]), values=values, 
            size=(self.n_users, self.n_items)
        )

        # 构造完整的邻接矩阵 (user_num + item_num, user_num + item_num)
        tmp_row = self.row
        tmp_col = self.col + self.n_users  # 物品索引整体右移 self.n_users
        tmp_values = values.clone()  # 复制 values 避免修改

        tmp_adj = torch.sparse_coo_tensor(
            indices=torch.stack([tmp_row, tmp_col]), values=tmp_values, 
            size=(self.n_users + self.n_items, self.n_users + self.n_items)
        )

        # 计算对称邻接矩阵 A + A^T
        self.joint_adjaceny_matrix = (tmp_adj + tmp_adj.t()).coalesce()

        # 计算度矩阵 D
        degree = torch.sparse.sum(self.joint_adjaceny_matrix, dim=1).to_dense()
        degree = torch.pow(degree, -0.5)
        degree[torch.isinf(degree)] = 0  # 避免无穷大的问题
        D_inverse = torch.diag(degree).to_sparse()

        # 计算对称归一化邻接矩阵 D^(-1/2) * A * D^(-1/2)
        self.norm_adj = torch.sparse.mm(
            torch.sparse.mm(D_inverse, self.joint_adjaceny_matrix), D_inverse
        ).coalesce()

        # 生成随机游走邻接矩阵
        joint_indices = self.norm_adj.indices()
        self.row = joint_indices[0]
        self.col = joint_indices[1]
        
        # 生成随机游走路径
        start = torch.arange(self.n_users + self.n_items)
        walk = random_walk(self.row, self.col, start, walk_length=self.walk_length)

        # 构造随机游走邻接矩阵
        self.rw_adj = torch.zeros((self.n_users + self.n_items, self.n_users + self.n_items))
        self.rw_adj = torch.scatter(self.rw_adj, 1, walk, 1).to_sparse()

        # 计算随机游走归一化
        degree = torch.sparse.sum(self.rw_adj, dim=1).to_dense()
        degree = torch.pow(degree, -1)
        degree[torch.isinf(degree)] = 0
        D_inverse = torch.diag(degree).to_sparse()
        self.rw_adj = torch.sparse.mm(D_inverse, self.rw_adj).to(self.device)

        # 确保所有计算的矩阵移动到 GPU
        self.norm_adj = self.norm_adj.to(self.device)
        
    def sparse_mx_vo_torch_sparse_tensor(self, sparse_mx):
        """Convert a scipy sparse matrix to a torch sparse tensor."""
        sparse_mx = sparse_mx.tocoo().astype(np.float32)
        indices = torch.from_numpy(np.vstack((sparse_mx.row, sparse_mx.col)).astype(np.int64))
        values = torch.from_numpy(sparse_mx.data)
        shape = torch.Size(sparse_mx.shape)
        return torch.sparse.FloatTensor(indices, values, shape)
    
    

